package com.lexorion.payroll.domain;import jakarta.persistence.*;import java.time.LocalDate;import java.util.UUID;import lombok.*;import org.hibernate.annotations.UuidGenerator;@Entity@Table(name="payroll_employees",uniqueConstraints=@UniqueConstraint(name="uk_payroll_employee_workspace_code",columnNames={"workspace_id","employee_code"}),indexes={@Index(name="idx_payroll_employee_workspace_status",columnList="workspace_id,payroll_status")})@Getter@Setter@NoArgsConstructor public class PayrollEmployee extends Auditable{@Id@UuidGenerator private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="workspace_id",nullable=false,updatable=false)private PayrollWorkspace workspace;@Column(name="employee_code",nullable=false,updatable=false,length=63)private String employeeCode;@Enumerated(EnumType.STRING)@Column(name="payroll_status",nullable=false,length=16)private PayrollStatus status;@Column(nullable=false,length=3)private String currency;@Enumerated(EnumType.STRING)@Column(name="pay_frequency",nullable=false,length=16)private PayFrequency payFrequency;@Column(name="effective_from",nullable=false)private LocalDate effectiveFrom;}
